package test;

import java.util.Arrays;

public class Example {
    public void doSomething(Object[] items) {
        // The explicit cast resolves the compiler warning.
        Arrays.asList("first", (java.lang.Object[]) items);
    }

    public void addElements(MyViewer viewer, MyRoot root, Object[] newElements) {
        viewer.add(root, (java.lang.Object[]) newElements);
    }
}

class MyViewer {
    public void add(MyRoot parent, Object... childElements) {}
}

